"use strict";exports.id=7861,exports.ids=[7861],exports.modules={97861:(a,b,c)=>{c.d(b,{Kr:()=>g,Ty:()=>d,$t:()=>f,eF:()=>e});let d=[{number:1,slug:"1",title:"Course Introduction: Building Our Class Community",unit:{number:1,title:"Foundations of Professional Healthcare Communication"},sessions:"1",goals:["professional-writing"],intro:["Welcome to Writing and Communication for Healthcare Professionals. This session is about getting to know the course, getting comfortable with your classmates and instructors, and beginning to think about why communication and writing matter in healthcare.","Do not worry about getting everything right today. Your first writing sample is a starting point, not a test."],essentialQuestion:{note:"The Instructor's Guide does not state an Essential Question for the orientation session. The 'Questions to think about' below are used in its place on the Brightspace Week 1 page. Confirm whether one should be added for consistency with Topics 2–10."},concepts:["Describe the purpose of the course and why strong writing matters in healthcare","Identify the types of writing used in healthcare workplaces","Explain how practice, feedback, and revision build a stronger writer","Locate course materials and assignments in Brightspace","Complete a short writing sample as a baseline"],grammar:{note:"The Instructor's Guide assigns no Grammar Focus to the orientation session; explicit grammar instruction begins with the Topic 2 diagnostic. Confirm whether this section should stay empty or preview the diagnostic."},wordListNumber:1,practice:[{kind:"word-bank",title:"Words to know",listNumber:1}],product:{note:"The guide lists a professional self-introduction writing warm-up for this session rather than a cumulative workplace product. The warm-up prompt appears under 'Think about' below. Confirm whether Topic 1 should carry a formal workplace product."},reflection:["Why does good writing matter in healthcare?","What makes communication clear, accurate, and professional?","What does it mean to become a better writer?","How can feedback and revision help me improve?","Writing warm-up: Think about a time when someone communicated something to you clearly — or when a message was confusing. What made the communication effective or ineffective? Write honestly and in your own words. This is not a grammar test."],beforeYouLeave:["Completed the Brightspace orientation activities","Participated in the class community activity","Completed the Writing Warm-Up in Amplify","Reviewed the Writing Portfolio information"],closingLine:"You are not expected to be a perfect writer when you begin this course. You are here to become a better one."},{number:2,slug:"2",title:"Foundations: Clear and Professional Communication",unit:{number:1,title:"Foundations of Professional Healthcare Communication"},sessions:"1–2",goals:["grammar-sentence","professional-writing","patient-centered"],essentialQuestion:"Why does clear writing matter in healthcare?",concepts:["Communication is a patient-safety issue, not only a matter of politeness","What makes healthcare writing effective","Clarity, correctness, and professionalism are three different things — a message can be correct and still unclear","Audience and purpose: who is reading this, and what do they need to do after reading it?","Introduction to the Communication Check, the five criteria you will use all term"],grammar:[{heading:"Diagnostic focus — a non-graded baseline",points:["Parts of speech and what each one does in a sentence","Subject and predicate","Complete sentences","Subject–verb agreement","Capitalization","Basic punctuation","Fragments","Run-ons","Pronoun clarity"]}],wordListNumber:2,practice:[{kind:"grammar-drill",title:"Grammar diagnostic",instructions:"A baseline, not a grade. Answer honestly — the point is to find out what to work on, and every option explains itself.",items:[{id:"t2-sva-1",prompt:"Choose the sentence with correct subject–verb agreement.",principle:"The verb agrees with the subject, not with a noun that happens to sit closest to it. Find the real subject first — here it is 'box', not 'gloves'.",choices:[{text:"The box of gloves are stored in the supply room.",correct:!1,rationale:"The subject is 'box', which is singular, so it takes 'is'. 'Gloves' is inside a prepositional phrase and cannot be the subject."},{text:"The box of gloves is stored in the supply room.",correct:!0,rationale:"Correct. The singular subject 'box' takes the singular verb 'is', regardless of the plural noun in between."},{text:"The box of gloves were stored in the supply room.",correct:!1,rationale:"'Were' is plural and past tense. The singular subject 'box' needs 'is' or 'was'."},{text:"The boxes of gloves is stored in the supply room.",correct:!1,rationale:"Here the subject 'boxes' is plural, so it needs 'are'. The subject and verb do not match."}]},{id:"t2-frag-1",prompt:"Which of these is a sentence fragment?",principle:"A complete sentence needs a subject and a verb and must express a complete thought. A group of words beginning with 'because', 'after', or 'while' needs a main clause attached to it.",choices:[{text:"Because the patient arrived without her insurance card.",correct:!0,rationale:"Correct. This has a subject and verb but begins with 'because', so it is a dependent clause left on its own — the reader is still waiting for what happened."},{text:"The patient arrived without her insurance card.",correct:!1,rationale:"This is complete: subject 'patient', verb 'arrived', and a finished thought."},{text:"She returned the next morning with it.",correct:!1,rationale:"Complete — subject 'she', verb 'returned', finished thought."},{text:"Verify insurance at check-in.",correct:!1,rationale:"This is an imperative sentence. The subject 'you' is understood rather than written, which is correct for an instruction."}]},{id:"t2-runon-1",prompt:"Which sentence is a run-on?",principle:"Two complete sentences cannot be joined by a comma alone. Fix a comma splice with a period, a semicolon, or a comma plus a joining word such as 'and', 'but', or 'so'.",choices:[{text:"The waiting room was full, the front desk called for help.",correct:!0,rationale:"Correct. Two complete sentences joined by only a comma — a comma splice. Use a period, a semicolon, or add 'so'."},{text:"The waiting room was full, so the front desk called for help.",correct:!1,rationale:"Correct as written. A comma plus the joining word 'so' properly connects two complete sentences."},{text:"The waiting room was full. The front desk called for help.",correct:!1,rationale:"Two correct sentences, separated by a period."},{text:"Because the waiting room was full, the front desk called for help.",correct:!1,rationale:"Correct. A dependent clause followed by a comma and a main clause."}]},{id:"t2-pronoun-1",prompt:"Which sentence has a pronoun that is unclear about who it refers to?",principle:"A pronoun must point to exactly one noun. When two people of the same gender appear in a sentence, repeat the name rather than using 'she' or 'he'.",choices:[{text:"When the nurse spoke with the patient, she seemed concerned.",correct:!0,rationale:"Correct. 'She' could mean the nurse or the patient. In documentation this ambiguity can change the meaning of the record — name the person."},{text:"When the nurse spoke with the patient, the patient seemed concerned.",correct:!1,rationale:"Clear. Repeating the noun removes any doubt about who was concerned."},{text:"The patient said she had not eaten since midnight.",correct:!1,rationale:"Clear. Only one person appears, so 'she' has one possible referent."},{text:"Dr. Reyes reviewed the chart before he entered the room.",correct:!1,rationale:"Clear. Only one person is named, so 'he' is unambiguous."}]},{id:"t2-caps-1",prompt:"Which sentence is capitalized correctly?",principle:"Capitalize proper nouns — specific names of people, places, departments, days, and months. Do not capitalize a general job title or a common noun just because it feels important.",choices:[{text:"The Patient will see the Doctor on tuesday in Radiology.",correct:!1,rationale:"'Patient' and 'Doctor' are common nouns here and should be lowercase, and 'Tuesday' needs a capital."},{text:"The patient will see the doctor on Tuesday in Radiology.",correct:!0,rationale:"Correct. Common nouns stay lowercase, the day of the week is capitalized, and Radiology as a named department is capitalized."},{text:"the patient will see the doctor on Tuesday in radiology.",correct:!1,rationale:"The first word of a sentence must be capitalized, and the named department Radiology should be too."},{text:"The Patient will see Dr. Okafor on tuesday in radiology.",correct:!1,rationale:"'Dr. Okafor' is correct, but 'Patient' should be lowercase and 'Tuesday' needs a capital."}]},{id:"t2-prof-1",prompt:"A coworker needs the updated supply list. Which message is appropriate for the workplace?",principle:"Professional does not mean stiff. It means clear about what you need, specific about when, and respectful of the reader's time.",choices:[{text:"hey can u send me that list asap?? need it",correct:!1,rationale:"Missing capitalization and punctuation, abbreviations, and no specificity about which list or when it is needed."},{text:"Send the supply list.",correct:!1,rationale:"Grammatically correct but abrupt, and it gives no deadline or context. Correct is not the same as professional."},{text:"Hi Marcus — could you send me the updated supply list before Thursday's order? Thank you.",correct:!0,rationale:"Correct. It greets the reader, names exactly what is needed, gives a deadline and a reason, and stays brief."},{text:"I was wondering if at some point when you have a moment you might possibly be able to look into sending over that list we discussed.",correct:!1,rationale:"Polite but wordy and vague. The reader still does not know which list or when it is due."}]},{id:"t2-clarity-1",prompt:"Which version of this instruction is clearest for a patient?",principle:"Clarity means the reader knows exactly what to do. Replace vague timing with specific timing, and jargon with plain words.",choices:[{text:"Take the medication as directed with adequate hydration.",correct:!1,rationale:"'As directed' and 'adequate hydration' assume the patient already knows. Neither tells them what to actually do."},{text:"Take one tablet with a full glass of water every morning with breakfast.",correct:!0,rationale:"Correct. It states how much, with what, how often, and when — nothing is left for the patient to guess."},{text:"Administer one tablet PO QAM with food.",correct:!1,rationale:"This is written for a clinician, not a patient. Abbreviations like PO and QAM belong in the record, not in patient instructions."},{text:"Take your medication regularly and stay hydrated.",correct:!1,rationale:"'Regularly' could mean anything. The patient cannot follow this without more information."}]},{id:"t2-subject-1",prompt:"What is the complete subject of this sentence? “The new front-desk assistant verified the patient's insurance before the appointment.”",principle:"The complete subject is who or what the sentence is about, together with the words describing it. Find the verb first, then ask who or what did it.",choices:[{text:"assistant",correct:!1,rationale:"That is the simple subject. The complete subject also includes the words describing it."},{text:"The new front-desk assistant",correct:!0,rationale:"Correct. The verb is 'verified'; who verified? The new front-desk assistant — including all its describing words."},{text:"the patient's insurance",correct:!1,rationale:"That is the object — what was verified, not who did the verifying."},{text:"before the appointment",correct:!1,rationale:"That is a prepositional phrase telling you when. It cannot be the subject."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:2}],product:{label:"Professional patient or staff communication",description:"Write a short professional communication from the scenario below. It must apply this topic's grammar and spelling, use a professional tone, stay clear, and keep to objective language. Aim for four to six sentences — brevity is part of the skill.",scenario:"A patient has called the office asking to move an appointment that is scheduled for Thursday. The next opening with her provider is the following Tuesday at 10:00 a.m. She also asked whether she still needs to fast beforehand; the answer is yes, for eight hours. Write the message she will receive."},reflection:["Read your draft out loud. Where did you stumble? That is usually where the reader will too.","Did you tell the reader what to do next, or only give them information?","Could someone outside healthcare understand every word you used?"],beforeYouLeave:["Completed the grammar diagnostic","Reviewed Word Bank List 2, including the confusable pairs","Drafted the patient or staff communication","Checked your draft against all five Communication Check criteria"]},{number:3,slug:"3",title:"Writing About Patients: Objective Documentation",unit:{number:2,title:"Clinical Documentation"},sessions:"2",goals:["documentation","grammar-sentence","summarizing"],spiralsFrom:[2],essentialQuestion:"How can I document what happened without adding my opinions or assumptions?",concepts:["Why documentation must be precise and evidence-based — the record may become part of the professional and legal record","Objective information (what you measured, saw, or heard) versus subjective information (what the patient reported)","Objective language versus judgmental language","Facts versus interpretations","Observations versus assumptions — you can document that a patient winced; you cannot document that they were in severe pain"],grammar:[{heading:"Nouns, verbs, and pronouns",points:["Nouns name a person, place, thing, or idea","Subject versus object: who is doing the action, and who receives it","Pronoun forms, and keeping the reference unmistakable"]},{heading:"Types of verbs",points:["Action verbs: what someone did — walked, reported, refused","Linking verbs and forms of 'to be': connect a subject to a description","Active voice through subject–verb placement: 'The patient refused the medication' rather than 'The medication was refused'"]}],wordListNumber:3,practice:[{kind:"sorter",title:"Fact or opinion?",instructions:"Sort each statement. If it could not be measured, quoted, or directly observed, it is not objective.",bins:[{id:"objective",label:"Objective",hint:"Measured, observed, or quoted"},{id:"subjective",label:"Opinion or assumption",hint:"Interpreted or judged"}],items:[{id:"t3-s1",text:"Blood pressure 148/92, right arm, seated.",bin:"objective",feedback:"A measurement with the conditions recorded. Anyone could verify it."},{id:"t3-s2",text:"Patient seems anxious about the procedure.",bin:"subjective",feedback:"'Seems' is the tell. You are interpreting a mental state you cannot observe directly."},{id:"t3-s3",text:"Patient states, “I have not eaten since yesterday morning.”",bin:"objective",feedback:"A direct quotation of what the patient reported. The quotation marks make clear it is their account, not your conclusion."},{id:"t3-s4",text:"Patient is being difficult about the blood draw.",bin:"subjective",feedback:"'Difficult' is a judgment about the person. Document the behavior instead: what did they say or do?"},{id:"t3-s5",text:"Patient withdrew their arm twice during the attempted venipuncture.",bin:"objective",feedback:"An observable action, counted. This is what 'difficult' should have been."},{id:"t3-s6",text:"Patient appears to be exaggerating the pain.",bin:"subjective",feedback:"This assigns a motive you cannot know, and it prejudices every clinician who reads the chart afterwards."},{id:"t3-s7",text:"Patient rated pain 8 out of 10 in the right lower abdomen.",bin:"objective",feedback:"Pain is self-reported, and recording the patient's own number is the objective way to capture it."},{id:"t3-s8",text:"Patient is non-compliant with the medication schedule.",bin:"subjective",feedback:"'Non-compliant' is a label. The fact is what they told you: how many doses, and what they said about why."},{id:"t3-s9",text:"Patient reports taking two of the four prescribed doses this week.",bin:"objective",feedback:"Specific, quoted from the patient, and free of any conclusion about why."},{id:"t3-s10",text:"Wound 3 cm, edges approximated, no drainage noted.",bin:"objective",feedback:"Measured and described. Another person examining it would write the same thing."}]},{kind:"rewrite",title:"Replace judgmental language",instructions:"Each entry below would be a problem in a real record. Write the objective version, then compare with a model.",items:[{id:"t3-r1",before:"Patient was rude and uncooperative during the visit.",problem:"Two judgments and no facts. A reader learns your opinion of the patient and nothing about what happened.",model:"Patient raised their voice when asked to repeat their date of birth and declined to complete the intake form.",rubric:["Describes observable behavior rather than labeling the person","Contains no words that judge character (rude, difficult, uncooperative)","A different staff member observing the same visit could have written it","Grammar and spelling are correct"]},{id:"t3-r2",before:"Patient obviously did not understand the instructions.",problem:"'Obviously' asserts something about the patient's mind. You can report what they said or did, not what they understood.",model:"When asked to repeat the medication schedule, patient stated, “I take them all at night, right?” The schedule is one tablet each morning.",rubric:["Reports what the patient said or did, not what they knew","Uses a direct quotation where the patient's own words matter","Includes the fact that makes the entry meaningful","Contains no words asserting a mental state"]},{id:"t3-r3",before:"Patient seemed fine and was probably just tired.",problem:"'Seemed', 'probably', and 'just' are all hedges around a guess. In a record that later matters, this entry says nothing.",model:"Patient was alert and oriented, answered all intake questions, and reported sleeping approximately four hours last night.",rubric:["Every statement is something observed or reported","No hedging words (seemed, probably, apparently, just)","Includes specifics rather than general impressions","Could be defended if the chart were reviewed"]}]},{kind:"grammar-drill",title:"Grammar and spelling corrections",instructions:"Nouns, verbs, and pronouns, in the sentences you will actually write.",items:[{id:"t3-g1",prompt:"Which sentence puts the action in the active voice, with the doer as the subject?",principle:"Active voice names who did what. In documentation this matters: 'the medication was refused' leaves out who refused it.",choices:[{text:"The medication was refused.",correct:!1,rationale:"Passive. The reader does not learn who refused — the patient, a family member, or someone else."},{text:"The patient refused the medication.",correct:!0,rationale:"Correct. Subject (patient), action verb (refused), object (medication). Nothing is left to inference."},{text:"Refusal of the medication occurred at 1400.",correct:!1,rationale:"The time is useful but the doer has vanished into a noun. Who refused?"},{text:"It was decided that the medication would not be given.",correct:!1,rationale:"Doubly vague — no doer, and 'decided' hides whether the patient declined or a clinician withheld it."}]},{id:"t3-g2",prompt:"Which sentence uses a pronoun that a reader could not misread?",principle:"A pronoun must have exactly one possible antecedent. When two people appear, repeat the noun.",choices:[{text:"The assistant told the patient that she needed to fast.",correct:!1,rationale:"'She' could be the assistant or the patient. In a record, that ambiguity can invert the meaning."},{text:"The assistant told the patient that the patient needed to fast.",correct:!0,rationale:"Correct. Repeating the noun is slightly clunky and completely unambiguous. Clarity wins."},{text:"She told her that she needed to fast.",correct:!1,rationale:"Three pronouns and no clear referent for any of them."},{text:"The patient was told by her that she needed to fast.",correct:!1,rationale:"Passive and still ambiguous — both 'her' and 'she' are unresolved."}]},{id:"t3-g3",prompt:"Which entry documents an observation rather than an assumption?",principle:"You may document what you saw, measured, or were told. You may not document what you concluded about a person.",choices:[{text:"Patient was clearly in a lot of pain.",correct:!1,rationale:"'Clearly' and 'a lot' are your assessment. Record the behavior or the patient's own rating."},{text:"Patient guarded the right side when standing and rated pain 7 out of 10.",correct:!0,rationale:"Correct. One observed behavior and one self-reported number — both verifiable."},{text:"Patient did not seem to be in much distress.",correct:!1,rationale:"'Did not seem' is an impression, and a wrong one in the record can affect later care decisions."},{text:"Patient is a complainer.",correct:!1,rationale:"A label attached to the person. This has no clinical value and would be indefensible if the record were reviewed."}]},{id:"t3-g4",prompt:"Which sentence is spelled correctly?",principle:"Topic 3 words: evidence, Wednesday, dilated, nauseous, consciousness. Wednesday keeps a silent 'd' most people drop.",choices:[{text:"Patient reported feeling nauseus on Wendsday.",correct:!1,rationale:"Two errors: 'nauseous' and 'Wednesday'."},{text:"Patient reported feeling nauseous on Wednesday.",correct:!0,rationale:"Correct on both. Note the silent 'd' in Wednesday."},{text:"Patient reported feeling nauseous on Wendesday.",correct:!1,rationale:"'Nauseous' is right; 'Wednesday' is not."},{text:"Patient reported feeling nausious on Wednesday.",correct:!1,rationale:"'Wednesday' is right; the word is 'nauseous'."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:3}],product:{label:"Brief patient encounter note",description:"Write a short objective encounter note from the scenario below. Include what you observed, what the patient reported (quoted where their words matter), and what was done. Include no interpretations, no labels, and no conclusions about the patient. Four to six sentences.",scenario:"A patient arrives 20 minutes late for a scheduled blood pressure check. They tell you they ran for the bus. You measure blood pressure at 152/94 in the right arm, seated. They mention they stopped taking one of their medications about two weeks ago because it “made them feel strange,” and they have not called the office about it. You take a second reading after five minutes of rest: 138/86."},reflection:["Read your note and circle every word that describes what you thought rather than what you saw. Remove them.","Would another assistant who saw the same visit write something close to what you wrote?","If this note were read aloud two years from now, is there anything in it you would want to take back?"],beforeYouLeave:["Completed the fact-or-opinion sort","Rewrote all three judgmental entries and scored them against the rubric","Reviewed Word Bank List 3","Drafted the encounter note and checked it against the Communication Check"]},{number:4,slug:"4",title:"SOAP Notes: Organizing Clinical Information",unit:{number:2,title:"Clinical Documentation"},sessions:"1",goals:["documentation","grammar-sentence","summarizing"],spiralsFrom:[2,3],essentialQuestion:"How does organized documentation help another healthcare professional understand the patient?",concepts:["The purpose of clinical documentation: someone who was not there must be able to reconstruct what happened","SOAP structure — Subjective, Objective, Assessment, Plan","Subjective is what the patient tells you; Objective is what you measure or observe","Assessment and Plan are the provider's clinical judgment — know where your contribution ends","Relevant versus irrelevant information: a note that includes everything hides what matters","Documentation sequence: information in a predictable order can be read quickly under pressure"],grammar:[{heading:"Agreements",points:["Subject–verb agreement, including when a phrase separates the subject from its verb","Pronoun–noun agreement","Clear pronoun reference — every pronoun points to exactly one noun"]}],wordListNumber:4,practice:[{kind:"sorter",title:"Sort into S, O, A, and P",instructions:"Which section does each piece of information belong in? Ask who the information came from and whether it is measured or judged.",bins:[{id:"s",label:"Subjective",hint:"What the patient reports"},{id:"o",label:"Objective",hint:"What you measure or observe"},{id:"a",label:"Assessment",hint:"The provider's clinical judgment"},{id:"p",label:"Plan",hint:"What will happen next"}],items:[{id:"t4-s1",text:"“My throat has been sore for three days.”",bin:"s",feedback:"The patient's own report, in their own words. Subjective."},{id:"t4-s2",text:"Temperature 100.8\xb0F, oral.",bin:"o",feedback:"A measurement you took. Objective."},{id:"t4-s3",text:"Rapid strep test performed; result negative.",bin:"o",feedback:"A test you performed and its result. Objective — the finding, not what it means."},{id:"t4-s4",text:"Likely viral pharyngitis.",bin:"a",feedback:"A clinical conclusion drawn from the findings. Assessment — and the provider's to make, not yours."},{id:"t4-s5",text:"Return in 5 days if symptoms have not improved.",bin:"p",feedback:"What happens next. Plan."},{id:"t4-s6",text:"“I've been taking ibuprofen but it isn't helping much.”",bin:"s",feedback:"Reported by the patient. Subjective, even though it concerns a medication."},{id:"t4-s7",text:"Throat erythematous, no exudate noted.",bin:"o",feedback:"An observation from examination. Objective."},{id:"t4-s8",text:"Supportive care discussed; fluids and rest advised.",bin:"p",feedback:"The course of action decided. Plan."}]},{kind:"sequencer",title:"Put the note in order",instructions:"Arrange these into the sequence a colleague could read quickly under pressure.",items:[{id:"t4-q1",text:"Subjective — the patient's reported symptoms and history",position:1,reason:"The note opens with why the patient came, in their own account. It frames everything that follows."},{id:"t4-q2",text:"Objective — vital signs, examination findings, test results",position:2,reason:"What was measured comes after what was reported, so the reader can compare the two."},{id:"t4-q3",text:"Assessment — the provider's clinical impression",position:3,reason:"Judgment follows evidence. An assessment stated before its findings cannot be evaluated."},{id:"t4-q4",text:"Plan — treatment, instructions, and follow-up",position:4,reason:"The note ends with what happens next, which is what the next reader most often needs."}]},{kind:"grammar-drill",title:"Agreement and documentation editing",instructions:"Spot the agreement error, and the entry that oversteps.",items:[{id:"t4-g1",prompt:"Which sentence has correct subject–verb agreement?",principle:"A phrase between the subject and the verb does not change the subject. 'Each' and 'every' are singular.",choices:[{text:"Each of the test results were reviewed with the patient.",correct:!1,rationale:"'Each' is singular, so it takes 'was'. 'Results' is not the subject."},{text:"Each of the test results was reviewed with the patient.",correct:!0,rationale:"Correct. 'Each' is singular and takes the singular verb 'was'."},{text:"Each of the test result were reviewed with the patient.",correct:!1,rationale:"Two errors: 'result' should be plural in the phrase, and the verb should be 'was'."},{text:"Each of the test results are reviewed with the patient.",correct:!1,rationale:"'Are' is plural. 'Each' requires 'is' or 'was'."}]},{id:"t4-g2",prompt:"A medical assistant is writing a SOAP note. Which entry is outside their scope?",principle:"Medical assistants document what the patient reported and what was measured. Assessment is clinical judgment and belongs to the provider.",choices:[{text:"S: “My throat has been sore for three days.”",correct:!1,rationale:"A quoted patient report. Squarely within scope."},{text:"O: Temperature 100.8\xb0F, oral. Throat erythematous.",correct:!1,rationale:"Measurements and observations. Within scope."},{text:"A: Likely viral pharyngitis; antibiotics not indicated.",correct:!0,rationale:"Correct — this is the problem entry. It is a diagnosis and a treatment judgment, both of which belong to the provider."},{text:"P: Patient given written instructions for fluids and rest.",correct:!1,rationale:"Recording that instructions were given is documentation of what was done. Within scope."}]},{id:"t4-g3",prompt:"Which piece of information does NOT belong in this visit's note for a sore throat?",principle:"Relevance is a safety feature. A note padded with unrelated detail buries the information the next reader needs.",choices:[{text:"Onset and duration of the sore throat",correct:!1,rationale:"Directly relevant to why the patient came."},{text:"Current temperature",correct:!1,rationale:"Relevant — it bears on the presenting complaint."},{text:"The patient mentioned they are planning a holiday next month",correct:!0,rationale:"Correct. Pleasant conversation, no clinical bearing. Including it lengthens the note and hides what matters."},{text:"Medications the patient has already tried",correct:!1,rationale:"Relevant — it affects what to try next."}]}]},{kind:"builder",storageKey:"soap",title:"Build a SOAP note",instructions:"Write each section from the case below. Keep Subjective in the patient's words and Objective to what was measured. For Assessment, write what a provider would need from you — not a diagnosis of your own.",scenario:"A patient comes in reporting a sore throat that began three days ago. They say it hurts most when swallowing and that ibuprofen has helped only a little. They deny cough. You measure temperature 100.8\xb0F oral, pulse 88, respirations 16. On inspection the throat appears red with no visible white patches. A rapid strep test is performed and is negative. The provider advises fluids, rest, and a return visit in five days if there is no improvement.",fields:[{id:"s",label:"S — Subjective",prompt:"What the patient reported. Quote them where their exact words matter.",expects:["sore throat","three days","3 days"],missingHint:"A reader needs the complaint and how long it has been going on."},{id:"o",label:"O — Objective",prompt:"What you measured and observed. Numbers with their units.",expects:["100.8","temp"],missingHint:"Include the vital signs you measured, with values."},{id:"a",label:"A — Assessment",prompt:"Summarize the findings for the provider. Do not write a diagnosis — that is the provider's.",rows:2},{id:"p",label:"P — Plan",prompt:"What was advised and what happens next, including follow-up.",expects:["five days","5 days","return","follow"],missingHint:"The plan should state the follow-up interval so the next reader knows when to expect them back."}]},{kind:"word-bank",title:"Words to spell",listNumber:4}],product:{label:"Basic SOAP note",description:"Complete the guided SOAP note from the case above. Each section holds only what belongs in it, agreements are correct, and every pronoun has one clear referent. Submit through Brightspace."},reflection:["Could a colleague who has never met this patient act on your note?","Is anything in your Objective section actually an interpretation?","Did you include anything a reader does not need?"],beforeYouLeave:["Sorted all eight items into S, O, A, and P","Put the note sections into the correct sequence","Completed the agreement drill","Built the SOAP note and ran the completeness check"]},{number:5,slug:"5",title:"Handoffs, Messages & Professional Communication",unit:{number:2,title:"Clinical Documentation"},sessions:"1",goals:["documentation","professional-writing","summarizing","grammar-sentence"],spiralsFrom:[3,4],essentialQuestion:"What information does another healthcare professional need from me to safely continue the patient's care?",concepts:["Relevant information: what the next person must know to act safely","Prioritization — the most important thing goes first, not last","Conciseness without omission","SBAR as a communication framework: Situation, Background, Assessment, Recommendation","Closed-loop communication — the receiver repeats it back so both people know it landed","Avoiding ambiguity: 'soon', 'a lot', and 'later' mean different things to different people"],grammar:[{heading:"Adjectives and adverbs",points:["What each one modifies: adjectives describe nouns, adverbs describe verbs, adjectives, and other adverbs","Changing adjectives into adverbs — usually by adding -ly","good / better / best, and the difference between 'good' and 'well'","less versus fewer: less for amounts you cannot count, fewer for things you can","much versus many, on the same principle"]},{heading:"Verb tenses",points:["Present, past, and future, and what each one signals in a handoff","Progressive forms (helping verb + -ing) for action that is ongoing right now","Avoiding shifting tenses mid-report, which makes the timeline unreadable"]}],wordListNumber:5,practice:[{kind:"grammar-drill",title:"Adjectives, adverbs, and tense",instructions:"The grammar of a handoff — precision about quantity, degree, and when.",items:[{id:"t5-g1",prompt:"Which sentence uses 'fewer' and 'less' correctly?",principle:"Fewer for things you can count individually. Less for quantities you measure rather than count.",choices:[{text:"The patient had less episodes of dizziness and fewer fluid intake today.",correct:!1,rationale:"Both are reversed. Episodes can be counted (fewer); fluid intake is measured (less)."},{text:"The patient had fewer episodes of dizziness and less fluid intake today.",correct:!0,rationale:"Correct. Countable episodes take 'fewer'; measurable intake takes 'less'."},{text:"The patient had less episodes of dizziness and less fluid intake today.",correct:!1,rationale:"'Episodes' are countable, so they need 'fewer'."},{text:"The patient had fewer episodes of dizziness and fewer fluid intake today.",correct:!1,rationale:"'Fluid intake' is measured, not counted, so it needs 'less'."}]},{id:"t5-g2",prompt:"Which sentence keeps the tense consistent?",principle:"Shifting tense mid-report makes the timeline ambiguous, and in a handoff the timeline is the point.",choices:[{text:"The patient arrived at 0900, reports chest tightness, and was given aspirin.",correct:!1,rationale:"Past, present, past. The reader cannot tell whether the chest tightness is current."},{text:"The patient arrived at 0900, reported chest tightness, and was given aspirin.",correct:!0,rationale:"Correct. All past tense — a consistent account of what has already happened."},{text:"The patient arrives at 0900, reported chest tightness, and is given aspirin.",correct:!1,rationale:"Present, past, present. The sequence is impossible to follow."},{text:"The patient was arriving at 0900 and reports chest tightness.",correct:!1,rationale:"The progressive form suggests an ongoing arrival, and the tense still shifts."}]},{id:"t5-g3",prompt:"Which phrase should be removed from a handoff because it is ambiguous?",principle:"Vague quantifiers are where handoffs fail. If two people could read it differently, replace it with a number or a time.",choices:[{text:"Pain rated 7 out of 10",correct:!1,rationale:"A specific self-reported number. Unambiguous."},{text:"Last dose given at 1400",correct:!1,rationale:"A specific time. Unambiguous."},{text:"Should be seen fairly soon",correct:!0,rationale:"Correct. 'Fairly soon' could mean ten minutes or two hours. Say when, or say what would trigger escalation."},{text:"Allergic to penicillin — hives and throat swelling",correct:!1,rationale:"Names the allergen and the reaction. Exactly what the next person needs."}]},{id:"t5-g4",prompt:"A colleague repeats your handoff back to you with one detail wrong. What should you do?",principle:"Closed-loop communication exists so errors surface at the handoff instead of at the bedside. The read-back working is the system succeeding.",choices:[{text:"Let it go — they have the important parts",correct:!1,rationale:"The detail you would let go is the one that reaches the patient wrong."},{text:"Correct the detail and ask them to repeat that part back again",correct:!0,rationale:"Correct. That is the loop closing. It costs ten seconds and is the entire point of a read-back."},{text:"Write it in the chart instead so it is documented",correct:!1,rationale:"Documenting is necessary but does not fix a colleague who is about to act on wrong information now."},{text:"Assume they misspoke and will remember correctly",correct:!1,rationale:"A read-back reflects what they actually heard. If it came back wrong, that is what they hold."}]}]},{kind:"rewrite",title:"Fix an unclear handoff",instructions:"Each of these was said at a shift change. Rewrite so the next person can act on it.",items:[{id:"t5-r1",before:"Room 4 isn't doing great, you might want to keep an eye on them.",problem:"No name, no measurement, no threshold. 'Keep an eye' does not say what to watch or what to do.",model:"Room 4, Ms. Alvarez: respirations rose from 16 this morning to 24 at 1430, oxygen saturation 92%. Recheck within the hour, and notify the provider if saturation drops below 90%.",rubric:["Identifies the patient by name, not by room alone","Includes measured values and how they changed","States what to do and when","States a threshold for escalation"]},{id:"t5-r2",before:"The patient in bed 2 has some allergies so be careful with meds.",problem:"'Some allergies' and 'be careful' give the receiver nothing usable. Which allergen, and what reaction?",model:"Bed 2, Mr. Osei: allergic to penicillin — reaction is hives and throat swelling. Documented in the chart and on his band.",rubric:["Names the specific allergen","States the specific reaction, not just that one exists","Confirms where it is documented","Contains no vague instruction like 'be careful'"]}]},{kind:"builder",storageKey:"sbar",title:"Build an SBAR handoff",instructions:"Four sections. Situation is why you are calling right now; Background is what led here; Assessment is what you are seeing; Recommendation is what you are asking for.",scenario:"You are a patient care technician on a medical unit. Ms. Lena Okafor in room 312 was admitted two days ago for management of a leg infection. This morning her pulse was 74 and she was talkative. At 1500 you record pulse 112, respirations 24, temperature 101.6\xb0F, and she is quieter than usual and says she feels “strange.” Her blood pressure is 98/60, down from 128/78 this morning. You are calling the nurse.",fields:[{id:"s",label:"S — Situation",prompt:"Who you are, who the patient is, and why you are calling — in one or two sentences.",expects:["okafor","312"],missingHint:"Identify the patient by name or room so the nurse knows immediately who this concerns.",rows:2},{id:"b",label:"B — Background",prompt:"The relevant history. Why is this patient here, and what has been happening?",expects:["infection","admitted"],missingHint:"Include why the patient is admitted — it frames everything else."},{id:"a",label:"A — Assessment",prompt:"What you are observing now, with numbers and how they have changed. Report; do not diagnose.",expects:["112","101.6","24","98"],missingHint:"Include the measured values. A change described without numbers cannot be judged."},{id:"r",label:"R — Recommendation",prompt:"What you are asking for. Be direct — 'I need you to come and see her now' is appropriate.",expects:["see","come","assess","review","now"],missingHint:"State what you want to happen. A report with no request leaves the nurse to guess the urgency.",rows:2}]},{kind:"word-bank",title:"Words to spell",listNumber:5}],product:{label:"Written handoff / SBAR message",description:"Produce a written SBAR communication from the scenario above. It must be complete enough that the receiver needs to ask you nothing, and short enough to be read in under thirty seconds."},reflection:["If the person receiving this could not reach you afterwards, would they still have everything they need?","Did you state what you want to happen, or only what you observed?","Are there any vague quantifiers left — soon, a lot, a bit, slightly?"],beforeYouLeave:["Completed the adjective, adverb, and tense drill","Rewrote both unclear handoffs","Built the SBAR and ran the completeness check","Reviewed Word Bank List 5, including the spiral words"]},{number:6,slug:"6",title:"Writing Clear Patient Instructions",unit:{number:3,title:"Patient Communication"},sessions:"2",goals:["patient-centered","grammar-sentence","professional-writing"],spiralsFrom:[2,3],essentialQuestion:"How do I communicate healthcare information so a patient can actually understand and use it?",concepts:["Health literacy — a large share of adults find standard medical instructions hard to act on, and that says nothing about their intelligence","Medical jargon versus patient-friendly language","Sequencing: instructions in the order the patient will do them","Audience awareness — you are not writing for a colleague","Tell the patient what to do, rather than only giving them information"],grammar:[{heading:"Strong sentences",points:["Simple versus complex sentences, and why simple usually wins in instructions","Sentence fragments — and the one place they are acceptable","Run-ons and comma splices","Transition words that show sequence: first, next, then, after, finally"]},{heading:"Imperative sentences",points:["The imperative gives a direct instruction: 'Take one tablet each morning'","The subject 'you' is understood rather than written","Imperatives are shorter and clearer than 'the patient should' constructions"]}],wordListNumber:6,practice:[{kind:"matcher",title:"Translate the jargon",instructions:"Match each clinical term to plain language, then practise saying it to a patient.",pairs:[{id:"t6-m1",term:"hypertension",plain:"high blood pressure",explanation:"Your blood pressure is higher than it should be. That means your heart is working harder than it needs to."},{id:"t6-m2",term:"NPO after midnight",plain:"nothing to eat or drink after midnight",explanation:"Do not eat or drink anything — including water — after midnight tonight. If you take morning medications, ask us which ones to take with a small sip."},{id:"t6-m3",term:"administer topically",plain:"put it on the skin",explanation:"Put a thin layer on the skin over the sore area. It is not something you swallow."},{id:"t6-m4",term:"adverse reaction",plain:"a harmful side effect",explanation:"If the medicine makes you feel worse rather than better, stop taking it and call us right away."},{id:"t6-m5",term:"ambulate",plain:"walk",explanation:"Try to get up and walk a short distance a few times a day, as long as it does not hurt."},{id:"t6-m6",term:"contraindicated",plain:"not safe to use in your case",explanation:"This medicine is not safe to take with the other one you are on, so we are using a different one."}]},{kind:"sequencer",title:"Put the instructions in a safe order",instructions:"These wound-care steps are scrambled. Order them the way the patient will actually do them.",items:[{id:"t6-q1",text:"Wash your hands with soap and water.",position:1,reason:"Hand washing comes first. Touching a wound with unwashed hands is how an infection starts, so this cannot come later."},{id:"t6-q2",text:"Take off the old bandage and throw it away.",position:2,reason:"The old dressing comes off before you can see or clean the wound."},{id:"t6-q3",text:"Rinse the wound gently with clean water.",position:3,reason:"Clean the wound once it is uncovered and before anything new goes on it."},{id:"t6-q4",text:"Pat the skin around the wound dry with a clean towel.",position:4,reason:"A dressing will not stick to wet skin, so drying comes after rinsing and before the new bandage."},{id:"t6-q5",text:"Put on a new bandage.",position:5,reason:"The new dressing goes on last, over a clean and dry area."},{id:"t6-q6",text:"Wash your hands again.",position:6,reason:"Hand washing bookends the task. Your hands touched a used dressing, so they are washed again at the end."}]},{kind:"rewrite",title:"Fix confusing instructions",instructions:"Each of these was given to a real-seeming patient and did not work. Rewrite it.",items:[{id:"t6-r1",before:"Patient should administer the prescribed analgesic PRN for post-operative discomfort and monitor the incision site for signs of infection.",problem:"Written for a colleague. 'Analgesic', 'PRN', 'post-operative', and 'signs of infection' all assume training the patient does not have.",model:"Take one pain tablet when you need it, up to four times a day. Look at the cut once a day. Call us if it becomes more red, more painful, or starts leaking fluid, or if you get a fever.",rubric:["Uses the imperative — tells the patient what to do","Replaces every piece of jargon with a plain word","Says what 'signs of infection' actually look like","Gives a specific limit or frequency, not 'as needed'"]},{id:"t6-r2",before:"Take your medication regularly and be sure to stay well hydrated throughout the day.",problem:"'Regularly' and 'well hydrated' mean nothing specific. The patient cannot follow this even if they want to.",model:"Take one tablet every morning with breakfast. Drink about six to eight glasses of water a day.",rubric:["States how much and how often, with numbers","Ties the dose to something in the patient's day","Replaces vague quantifiers with specific amounts","Would produce the same behavior from any two readers"]},{id:"t6-r3",before:"If symptoms worsen or fail to improve within an appropriate timeframe, contact the office.",problem:"The patient does not know what 'worsen' means here or what an appropriate timeframe is. Under pressure they will guess, and they may guess late.",model:"Call us if the pain gets worse, if you get a fever over 100.4\xb0F, or if you are not feeling better in three days. If you have trouble breathing, call 911.",rubric:["Names the specific symptoms that should prompt a call","Gives a number for the timeframe","Separates 'call us' from 'this is an emergency'","Could be acted on by someone frightened and distracted"]}]},{kind:"grammar-drill",title:"Fragments, run-ons, and the imperative",instructions:"The sentence grammar that makes instructions work.",items:[{id:"t6-g1",prompt:"Which is the clearest instruction for a patient?",principle:"The imperative gives a direct instruction with the subject 'you' understood. It is shorter and leaves less room for doubt.",choices:[{text:"The patient should ensure that the medication is taken each morning.",correct:!1,rationale:"Third person and passive. The patient reading it may not register that 'the patient' means them."},{text:"Take one tablet each morning with breakfast.",correct:!0,rationale:"Correct. Imperative, specific, and tied to a moment in the patient's day."},{text:"Medication administration should occur in the morning hours.",correct:!1,rationale:"No doer, no dose, and 'morning hours' is vaguer than 'with breakfast'."},{text:"It is recommended that morning dosing be observed.",correct:!1,rationale:"Doubly passive and reads as optional. A recommendation the patient may not follow."}]},{id:"t6-g2",prompt:"Which sentence is a run-on that needs fixing?",principle:"Two complete sentences joined by only a comma is a comma splice. In instructions this matters, because the reader loses where one step ends.",choices:[{text:"Wash your hands, then remove the old bandage.",correct:!1,rationale:"Correct as written. 'Then' plus a comma links the steps properly."},{text:"Wash your hands, remove the old bandage, rinse the wound with clean water, pat it dry, put on a new bandage.",correct:!0,rationale:"Correct — this is the run-on. Five instructions strung together with commas. Break them into separate sentences or a numbered list."},{text:"Wash your hands. Remove the old bandage.",correct:!1,rationale:"Two clear sentences, correctly separated."},{text:"After washing your hands, remove the old bandage.",correct:!1,rationale:"Correct. A dependent clause followed by a main clause, properly punctuated."}]},{id:"t6-g3",prompt:"Which transition word best signals that this is the last step?",principle:"Sequence transitions tell the reader where they are in a process. Using them consistently prevents a patient stopping halfway.",choices:[{text:"Also",correct:!1,rationale:"'Also' adds an item without signalling position. The reader does not know they are finishing."},{text:"Finally",correct:!0,rationale:"Correct. 'Finally' tells the reader this is the last step, which is genuinely reassuring in a set of instructions."},{text:"However",correct:!1,rationale:"'However' signals contrast, which would confuse a sequence."},{text:"Meanwhile",correct:!1,rationale:"'Meanwhile' suggests two things happening at once — the opposite of a final step."}]},{id:"t6-g4",prompt:"Which sentence uses 'once' and 'ones' correctly?",principle:"Topic 6 confusables. 'Once' means one time; 'ones' is the plural of 'one' standing in for a noun.",choices:[{text:"Change the bandage ones a day and use the clean once from the box.",correct:!1,rationale:"Both are reversed."},{text:"Change the bandage once a day and use the clean ones from the box.",correct:!0,rationale:"Correct. 'Once a day' means one time daily; 'the clean ones' stands in for 'the clean bandages'."},{text:"Change the bandage once a day and use the clean once from the box.",correct:!1,rationale:"'Once a day' is right, but the second should be 'ones'."},{text:"Change the bandage ones a day and use the clean ones from the box.",correct:!1,rationale:"The second is right; the first should be 'once'."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:6}],product:{label:"Patient instruction sheet",description:"Write a one-page instruction sheet a patient could follow at home without calling for clarification. Use imperatives, number the steps, replace every piece of jargon, and say specifically when to call the office and when to call 911.",scenario:"Choose one: caring for a wound after minor stitches; preparing for a procedure that requires nothing to eat or drink after midnight; taking a new blood pressure medication; or monitoring blood pressure at home with a cuff."},reflection:["Give your sheet to someone outside healthcare. Ask them to tell you what they would do first — not whether it makes sense.","Did you say what to do, or only what the situation is?","Is there any word on the page you would not use with a neighbour?"],beforeYouLeave:["Matched all six jargon terms and drafted plain-language explanations","Put the wound-care steps into a safe order","Rewrote all three confusing instructions","Drafted the instruction sheet and checked it against the Communication Check"]},{number:7,slug:"7",title:"Patient Messages, Reminders & Follow-Up",unit:{number:3,title:"Patient Communication"},sessions:"1–2",goals:["patient-centered","professional-writing","grammar-sentence"],spiralsFrom:[2,3,6],essentialQuestion:"How can I communicate important information briefly without sounding abrupt or unclear?",concepts:["Concise writing — short is not the same as curt","Essential versus unnecessary information: what does the reader need to act?","Professional tone in a very short message, where there is no room to recover from a bad line","Patient-centered language","A call to action — every message should make clear what happens next and who does it","Confirming understanding without sounding like a test"],grammar:{note:"The Instructor's Guide directs this topic to revisit earlier grammar rather than introduce new items, and does not specify which. The practice below spirals subject–verb agreement, fragments and run-ons, and pronoun clarity from Topics 2, 3, and 6. Confirm which items should be prioritized here."},wordListNumber:7,practice:[{kind:"choose-best",title:"Too much, too little, or just right?",scenario:"A patient is due for a follow-up appointment on Tuesday 14 October at 10:00 a.m. with Dr. Reyes. They need to arrive 15 minutes early and bring their current medication list. You are writing the reminder message they will see in the patient portal.",instructions:"One of these is right. The others fail in a specific way — read every explanation.",items:[{id:"t7-c1",prompt:"Which reminder should you send?",principle:"A good reminder carries exactly what the patient must know to show up correctly: when, where, and what to bring. Anything else competes with those three.",choices:[{text:"Appointment Tuesday 10am.",correct:!1,rationale:"Too little. No date, no provider, no arrival time, nothing about the medication list. The patient may arrive on the wrong Tuesday."},{text:"Hello, we hope this message finds you well. We are writing to remind you that as part of our ongoing commitment to your continued health and wellbeing, we have you scheduled for a follow-up consultation appointment with one of our providers here at the practice. Please make every effort to arrive in a timely manner and bring along any relevant materials.",correct:!1,rationale:"Too much, and it still omits the date, the time, the provider, and what to bring. Length is not the same as completeness."},{text:"Reminder: follow-up with Dr. Reyes on Tuesday, 14 October at 10:00 a.m. Please arrive by 9:45 and bring your current medication list. Call 555-0134 if you need to reschedule.",correct:!0,rationale:"Correct. Date, time, provider, arrival time, what to bring, and what to do if it does not work — in four lines."},{text:"You have an appointment coming up soon. Don't forget to bring everything you need and don't be late.",correct:!1,rationale:"Vague on every point and faintly scolding. 'Don't be late' reads as an accusation rather than an arrival time."}]},{id:"t7-c2",prompt:"The patient replies asking whether they still need to fast. Fasting is not required. Which reply is best?",principle:"Answer the question first, then add anything else. A reply that buries the answer makes the patient read twice to find it.",choices:[{text:"No.",correct:!1,rationale:"Accurate and abrupt. A one-word reply to a worried question reads as dismissive, even when it is correct."},{text:"No fasting is needed for this visit — you can eat and drink normally. Please still bring your medication list. See you Tuesday at 10:00.",correct:!0,rationale:"Correct. Answers the question in the first four words, confirms what that means in practice, and repeats the key details."},{text:"Thanks for reaching out! Great question. Let me look into that for you and get back to you as soon as I can.",correct:!1,rationale:"Warm but useless — you already know the answer. Delaying a known answer wastes the patient's time and yours."},{text:"Fasting requirements vary by procedure type and are determined by the ordering provider based on the clinical indication.",correct:!1,rationale:"True in general and no help at all. The patient asked about their appointment, not about policy."}]}]},{kind:"tone",title:"Tone continuum",instructions:"Place each message, then rewrite the ones that miss. Watch the over-soft end as carefully as the blunt end.",samples:[{id:"t7-t1",text:"You missed your appointment yesterday. You need to call and reschedule.",band:0,feedback:"Blunt. It opens with the patient's failure and issues an order. Nothing here is untrue, and most people receiving it would feel told off.",professional:"We missed you at yesterday's appointment. When you have a moment, call us at 555-0134 and we will find a new time that works."},{id:"t7-t2",text:"Your results are in. Call the office.",band:1,feedback:"Abrupt, and in this context genuinely worrying — a patient reading it will assume the news is bad. Two more words would fix it.",professional:"Your test results are back and Dr. Reyes would like to go over them with you. Please call us at 555-0134 when you can. There is nothing urgent to worry about."},{id:"t7-t3",text:"Hi Ms. Alvarez — your prescription is ready for pickup at the front desk any time before 5:00 p.m. this week. Let us know if you need it sent to your pharmacy instead.",band:2,feedback:"Professional. Warm opening, specific information, a clear deadline, and an alternative offered. Nothing wasted."},{id:"t7-t4",text:"Hi there! I hope you don't mind me reaching out, and I'm so sorry to bother you — I was just wondering if you might possibly have a moment at some point to maybe think about scheduling that follow-up we mentioned, if that's at all convenient for you?",band:3,feedback:"Over-soft. So hedged that the patient may not realize anything is being asked. Apologizing for doing your job also undercuts you.",professional:"Hi Ms. Alvarez — it is time to book your follow-up. Call us at 555-0134 or reply here and we will get it scheduled."}]},{kind:"grammar-drill",title:"Spiral review",instructions:"Grammar from Topics 2, 3, and 6, in the short messages you are writing now.",items:[{id:"t7-g1",prompt:"Which message has correct subject–verb agreement?",principle:"Spiral from Topic 2. A phrase between subject and verb does not change which verb you need.",choices:[{text:"The list of your current medications are needed at check-in.",correct:!1,rationale:"The subject is 'list', which is singular, so it takes 'is'. 'Medications' sits inside a phrase."},{text:"The list of your current medications is needed at check-in.",correct:!0,rationale:"Correct. Singular subject 'list' takes 'is'."},{text:"The lists of your current medication is needed at check-in.",correct:!1,rationale:"Here the plural 'lists' would need 'are'."},{text:"Your current medications list are needed at check-in.",correct:!1,rationale:"'List' is still the subject and still singular."}]},{id:"t7-g2",prompt:"Which message avoids an unclear pronoun?",principle:"Spiral from Topic 3. In a short message there is no context to recover a pronoun's meaning from.",choices:[{text:"We sent your results to Dr. Reyes and she will call you about it.",correct:!1,rationale:"'It' has no clear referent — the results, the call, or something else. In a two-line message this is genuinely confusing."},{text:"We sent your results to Dr. Reyes, and she will call you to discuss them.",correct:!0,rationale:"Correct. 'Them' clearly refers to the results, and 'she' to Dr. Reyes."},{text:"They sent them to her and she will call you about them.",correct:!1,rationale:"Four pronouns, none anchored."},{text:"It was sent and they will be in touch about it.",correct:!1,rationale:"No named actor at all. The patient learns nothing."}]},{id:"t7-g3",prompt:"Which of these is a fragment that should not be sent as written?",principle:"Spiral from Topic 6. Fragments work in a bulleted list. In running message text they leave the reader waiting.",choices:[{text:"Because your insurance information has changed.",correct:!0,rationale:"Correct — this is the fragment. It begins with 'because' and never says what follows from it. The patient is left waiting for the point."},{text:"Please bring your new insurance card to your next visit.",correct:!1,rationale:"A complete imperative sentence."},{text:"Your insurance information has changed, so please bring your new card.",correct:!1,rationale:"Two clauses correctly joined by a comma and 'so'."},{text:"Bring your new card.",correct:!1,rationale:"Short but complete — an imperative with the subject 'you' understood."}]}]},{kind:"word-bank",title:"Words to spell",listNumber:7}],product:{label:"Patient portal message",description:"Write a patient portal message about an appointment, a follow-up, a preparation requirement, or missing information. Two to four sentences. It must answer the patient's likely question first, state clearly what happens next, and sound like a person wrote it.",scenario:"A patient's insurance changed since their last visit and the front desk could not verify coverage for Thursday's appointment. The visit can still go ahead, but they need to bring the new card, and if coverage cannot be verified they may be billed as self-pay. Write the message they will see."},reflection:["Read your message as though you were worried about your health. Does the first line reassure or alarm?","Is the action you want the patient to take stated, or implied?","Could you cut a sentence without losing anything the patient needs?"],beforeYouLeave:["Completed the too-much / too-little / just-right exercise","Placed all four messages on the tone continuum and rewrote the three that missed","Completed the spiral grammar review","Drafted the portal message and checked it against the Communication Check"]},{number:8,slug:"8",title:"Referrals, Prior Authorizations & Requests",unit:{number:3,title:"Patient Communication"},sessions:"1–2",sessionsNote:{note:"Source conflict: the Instructor's Guide summary table lists Topic 8 as 1 session; the detailed outline heading for Topic 8 says 2 sessions. Confirm which is correct — this also bears on the overall session count against the Fall 1 calendar."},goals:["professional-writing","documentation","summarizing"],spiralsFrom:[5,7],essentialQuestion:"How do I communicate a request so that another person has the information needed to act on it?",concepts:["Purpose and audience — a referral is read by someone with no knowledge of this patient","Required information: what the receiver must have before they can act","Concise requests — a request buried in narrative gets actioned last","Supporting information versus padding","Follow-up: a request with no tracking is a request that disappears","Documentation of communication — record that the request was made, when, and to whom"],grammar:[{heading:"Paragraph organization",points:["The topic sentence states the paragraph's point, usually first","Supporting details back it up, and each one earns its place","Logical order: the reader should never have to re-read to follow you","Transitions connect the sentences so the paragraph reads as one thought"]}],wordListNumber:8,practice:[{kind:"missing-info",title:"What is missing from this request?",instructions:"Read the referral request as the specialist's office would receive it. Check every required element that is not there.",sample:"Hi — we'd like to refer a patient to your office for the knee problem we discussed. She's been having trouble for a while now and our provider thinks she should be seen. Please let us know when you can fit her in. Thanks!",elements:[{id:"t8-e1",label:"Patient's full name and date of birth",present:!1,why:"Without an identifier the receiving office cannot open a record or match the referral to a person."},{id:"t8-e2",label:"Referring provider's name",present:!1,why:"The specialist needs to know who to send findings back to, and who authorized the referral."},{id:"t8-e3",label:"Reason for referral, stated specifically",present:!1,why:"'The knee problem we discussed' means nothing to an office that was not in the conversation."},{id:"t8-e4",label:"Relevant clinical history and duration",present:!1,why:"'Trouble for a while' gives the specialist no basis for triage. How long, and what has been tried?"},{id:"t8-e5",label:"Insurance information and authorization status",present:!1,why:"Many specialist visits require prior authorization. Omitting this guarantees a delay or a denied claim."},{id:"t8-e6",label:"Urgency or requested timeframe",present:!1,why:"'When you can fit her in' hands the triage decision to someone with no clinical information."},{id:"t8-e7",label:"Contact details for the referring office",present:!1,why:"If anything is unclear, the specialist's office needs a way to reach you quickly."},{id:"t8-e8",label:"A stated request",present:!0,why:"This one is present — the message does ask for an appointment. It is the only element that is."}]},{kind:"sequencer",title:"Order the request",instructions:"Arrange these into the order a busy reader can act on fastest.",items:[{id:"t8-q1",text:"State the request and who it concerns: referral for [patient name, DOB] to orthopedics.",position:1,reason:"The reader must know within one line what this is and who it is about, so they can route it before reading further."},{id:"t8-q2",text:"Give the reason for the referral, specifically.",position:2,reason:"The clinical reason determines who sees it and how urgently. It comes before the history that supports it."},{id:"t8-q3",text:"Supply the relevant history: duration, findings, and what has already been tried.",position:3,reason:"Supporting detail follows the point it supports. Leading with history buries the request."},{id:"t8-q4",text:"Provide insurance and authorization information.",position:4,reason:"Administrative detail comes after the clinical picture — necessary, but not what the reader needs first."},{id:"t8-q5",text:"State the requested timeframe and give your contact details.",position:5,reason:"The close tells the reader what you want and how to reach you if anything is missing."}]},{kind:"grammar-drill",title:"Topic sentences and transitions",instructions:"Paragraph organization — the grammar that makes a request readable.",items:[{id:"t8-g1",prompt:"Which sentence works best as the topic sentence of a referral paragraph?",principle:"A topic sentence states the paragraph's point. In a request, that means saying what you are asking for before you explain why.",choices:[{text:"Ms. Chen has been experiencing knee pain, and she also mentioned some difficulty sleeping, and her last visit was in March.",correct:!1,rationale:"Three unrelated facts and no point. The reader does not know what this paragraph is for."},{text:"We are requesting an orthopedic referral for Ms. Chen for right knee pain of four months' duration.",correct:!0,rationale:"Correct. States the request, the patient, the reason, and the duration in one sentence. Everything after it is support."},{text:"As you may know, knee pain is a common presenting complaint in primary care.",correct:!1,rationale:"General background that tells the reader nothing about this patient or this request."},{text:"Please see the attached.",correct:!1,rationale:"Makes the reader open a document before they know whether it is urgent or even theirs."}]},{id:"t8-g2",prompt:"Which transition correctly signals that the next sentence gives a result?",principle:"Transitions tell the reader how sentences relate. Using the wrong one sends them looking for a relationship that is not there.",choices:[{text:"However",correct:!1,rationale:"'However' signals contrast, not result."},{text:"Therefore",correct:!0,rationale:"Correct. 'Therefore' tells the reader that what follows is the consequence of what came before."},{text:"Similarly",correct:!1,rationale:"'Similarly' signals comparison between two like things."},{text:"Meanwhile",correct:!1,rationale:"'Meanwhile' signals simultaneous time, not consequence."}]},{id:"t8-g3",prompt:"A paragraph in your referral contains six sentences, one of which describes the patient's holiday plans. What should you do?",principle:"Every supporting detail must support the topic sentence. Detail that does not is padding, and padding is where the reader's attention goes to die.",choices:[{text:"Keep it — it gives the specialist a sense of the patient as a person",correct:!1,rationale:"The specialist needs clinical and administrative information. Personal detail that does not bear on care is a privacy question as well as a clarity one."},{text:"Remove it — it does not support the request, and it lengthens what a busy reader must get through",correct:!0,rationale:"Correct. If it does not help the reader act, it competes with what does. Minimum necessary applies to referrals too."},{text:"Move it to the end so it does not interrupt",correct:!1,rationale:"Moving irrelevant information does not make it relevant."},{text:"Put it in a separate paragraph",correct:!1,rationale:"Same problem, now with its own heading."}]}]},{kind:"builder",storageKey:"referral",title:"Build a referral request",instructions:"Write each part. The completeness check looks for the elements the receiving office cannot act without.",scenario:"Ms. Wen Chen, date of birth 4 March 1968, has had right knee pain for four months. It worsens on stairs and after standing for long periods. She has tried over-the-counter ibuprofen with partial relief. An X-ray taken last week showed changes consistent with osteoarthritis. Dr. Amara Reyes is referring her to orthopedics. Her insurance is Meridian Health, member number MH-4471902, and prior authorization has been obtained, reference PA-88213. Dr. Reyes would like her seen within four weeks. Your office number is 555-0134.",fields:[{id:"request",label:"The request",prompt:"One sentence: what you are asking for, for whom, and why. This is your topic sentence.",expects:["chen"],missingHint:"Name the patient — the receiving office cannot match a referral without an identifier.",rows:2},{id:"history",label:"Relevant history",prompt:"Duration, findings, and what has already been tried. Enough to triage, nothing more.",expects:["four months","4 months","x-ray","ibuprofen"],missingHint:"Include how long this has been going on and what has already been tried."},{id:"insurance",label:"Insurance and authorization",prompt:"Carrier, member number, and authorization reference if obtained.",expects:["meridian","mh-","pa-"],missingHint:"Include the carrier and the authorization reference, or the visit may be delayed or denied."},{id:"close",label:"Timeframe and contact",prompt:"When you would like the patient seen, and how to reach you.",expects:["four weeks","4 weeks","555"],missingHint:"State the requested timeframe and a contact number — otherwise triage and follow-up both stall.",rows:2}]},{kind:"word-bank",title:"Words to spell",listNumber:8}],product:{label:"Referral / prior authorization communication",description:"Produce a complete referral or prior authorization request from the case above. The receiving office should need to ask you nothing. Organize it in paragraphs with clear topic sentences."},reflection:["Read it as the specialist's scheduler. Could you book this patient without calling back?","Does each paragraph have one point, stated in its first sentence?","Is there anything here the receiving office does not need?"],beforeYouLeave:["Identified every missing element in the incomplete referral","Put the request into the order a busy reader can act on","Completed the topic sentence and transition drill","Built the referral and ran the completeness check"]}];function e(a){return d.find(b=>b.number===a)}function f(a){let b=d.findIndex(b=>b.number===a);return{previous:b>0?d[b-1]:void 0,next:b>=0&&b<d.length-1?d[b+1]:void 0}}let g=[{unit:1,unitTitle:"Foundations of Professional Healthcare Communication",number:1,title:"Course Introduction: Building Our Class Community",sessions:"1",product:"Professional self-introduction (writing warm-up)",built:!0},{unit:1,unitTitle:"Foundations of Professional Healthcare Communication",number:2,title:"Foundations: Clear and Professional Communication",sessions:"1–2",product:"Professional patient/staff communication",built:!0},{unit:2,unitTitle:"Clinical Documentation",number:3,title:"Writing About Patients: Objective Documentation",sessions:"2",product:"Brief patient encounter note",built:!0},{unit:2,unitTitle:"Clinical Documentation",number:4,title:"SOAP Notes: Organizing Clinical Information",sessions:"1",product:"Basic SOAP note",built:!0},{unit:2,unitTitle:"Clinical Documentation",number:5,title:"Handoffs, Messages & Professional Communication",sessions:"1",product:"Written handoff / SBAR message",built:!0},{unit:3,unitTitle:"Patient Communication",number:6,title:"Writing Clear Patient Instructions",sessions:"2",product:"Patient instruction sheet",built:!0},{unit:3,unitTitle:"Patient Communication",number:7,title:"Patient Messages, Reminders & Follow-Up",sessions:"1–2",product:"Patient portal message or reminder",built:!0},{unit:3,unitTitle:"Patient Communication",number:8,title:"Referrals, Prior Authorizations & Requests",sessions:"1–2",product:"Referral / prior authorization communication",built:!0},{unit:4,unitTitle:"Workplace & Team Communication",number:9,title:"Professional Emails & Workplace Messages",sessions:"2",product:"Professional email",built:!1},{unit:5,unitTitle:"Revision, AI & Integrated Communication",number:10,title:"Proofreading, Revision & AI as a Writing Coach",sessions:"2",product:"Revised healthcare communication",built:!1},{unit:6,unitTitle:"Final",number:"final",title:"Integrated Healthcare Communication & Grammar",sessions:"1",product:"3–4 original writings from one case + grammar/spelling quiz",built:!1}]}};